# Writes the generated reference tables in dev/parity/ from the JSON the other parity tools produce.
import os, json, re, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
os.chdir(os.environ.get("PARITY_WORK", r"D:\gemrb\.re"))
OUT = r"D:\gemrb\dev\parity"
J = lambda n: json.load(open(n))

# ---------------- opcodes
ops = J("opcodes.json"); opmap = J("opmap.json")["map"]; apply = J("orig_apply.json")
L = ["# Opcode parity table", "",
	"Generated by `tools/parity/gen_docs.py`. One row per effect opcode that PST's data (SPL/ITM/EFF/CRE, with",
	"Fixpack + UB) uses. **EE class**: the PST:EE effect class the same effect became, found by aligning the same",
	"spell/item in both games (`opmap.py`); EE renumbered PST's own opcodes (186+) into its 3xx range, so EE numbers",
	"differ. **Orig apply**: address of the original Torment.exe `ApplyEffect` (vtable slot 2 of the class built by",
	"`sub_4A5C21`), decompiled in `.re/orig/dump/dec/<addr>.c`. **GemRB note**: hints from GemRB's own source",
	"(FIXME/TODO, \"not implemented\"), not a verdict.", "",
	"| Op | GemRB name | GemRB fx | Uses | EE class (EE op) | Orig apply | GemRB note | Example users |",
	"|---|---|---|---|---|---|---|---|"]
for r in ops:
	m = opmap.get(str(r["op"]), [])
	ee = ", ".join("%s (%d)" % (x[2].replace("CGameEffect", ""), x[0]) for x in m[:2]) or "—"
	L.append("| %d | %s | `%s` | %d | %s | %s | %s | %s |" % (r["op"], r["name"], r["func"] or "—", r["uses"], ee,
		apply.get(str(r["op"])) or "**none**", r["stub"] or "", ", ".join(r["example"][:3])))
open(os.path.join(OUT, "opcodes.md"), "w", encoding="utf-8").write("\n".join(L) + "\n")

# ---------------- spells
gx = J("gemext.json"); beh = J("psbehav.json"); suite = {}
for l in open(r"D:\gemrb\dev\spell_suite.jsonl", encoding="utf-8"):
	try:
		d = json.loads(l); suite[d.get("resref", "").upper()] = d
	except Exception: pass
rep = {}
for l in open(r"D:\gemrb\dev\spell_report.md", encoding="utf-8"):
	m = re.match(r"\| (\w+) [^|]*\| \d+ \|[^|]*\| ([^|]*) \|", l)
	if m: rep[m.group(1)] = m.group(2).strip().replace("<br>", "; ")
L = ["# Hardcoded PST spells: EE engine vs GemRB", "",
	"Generated by `tools/parity/gen_docs.py`. PST hardcodes 36 spells as projectile classes (`CPsSpell*` in the",
	"PST:EE Linux binary, which keeps its symbols; the original exe builds the same objects in `sub_559A5D`). The",
	"SPL file only carries part of the spell: the class picks targets, rolls, applies extra effects and plays",
	"its own animations and sounds. GemRB approximates each with a `.pro` in `gemrb/unhardcoded/pst` plus",
	"helper SPLs named by the projectile's GemRB-only `failureSpell`/`successSpell` fields.", "",
	"- **Code ops**: effects the EE class creates in code (not in the SPL). Each must have a GemRB equivalent.",
	"- **Logic**: what the class does besides playing visuals.",
	"- **GemRB helpers**: helper SPLs the GemRB projectile casts, with their opcodes.",
	"- **Assets only EE uses**: animations/sounds the class plays that no GemRB file references.",
	"- **Suite**: last `tb_spell_suite.py` result.", "",
	"| Spell | Class | GemRB .pro | Code ops | Logic | GemRB helpers | Assets only EE uses | Suite |", "|---|---|---|---|---|---|---|---|"]
for r in gx:
	b = beh.get(r["cls"], {})
	helpers = "; ".join("%s: %s" % (k, ",".join(str(o) for o, _ in v[1])) for k, v in (r.get("ext") or {}).items() if v) or "—"
	L.append("| %s | %s | %s | %s | %s | %s | %s | %s |" % (r["spl"] or "?", r["cls"].replace("CPsSpell", ""),
		(r["gemrb_pro"] or "—") + ("" if r["gemrb_has"] else " **missing**"),
		", ".join("%d %s" % (o, n.replace("CGameEffect", "")) for o, n in b.get("opcodes", [])) or "—",
		", ".join(b.get("features", [])) or "—", helpers, " ".join(r["not_in_gemrb"][:12]) + (" …" if len(r["not_in_gemrb"]) > 12 else ""),
		rep.get(r["spl"] or "", "") or "not run"))
open(os.path.join(OUT, "spells.md"), "w", encoding="utf-8").write("\n".join(L) + "\n")

# ---------------- scripting
sc = J("scripts.json"); oa = J("orig_actions.json"); ot = set(J("orig_triggers.json"))
handled = set(oa["sprite"]) | set(oa["base"])
L = ["# Script actions and triggers", "",
	"Generated by `tools/parity/gen_docs.py` from every BCS and DLG in PST (+Fixpack/UB). **Orig**: whether the",
	"original exe has a handler (sprite-level switch `sub_76A7EA` or base switch `sub_44B099` for actions;",
	"`sub_453258`/`sub_778529` for triggers; event triggers below 0x4000 are handled elsewhere and not checked).",
	"Several PST ids have two names (`JoinParty`/`JoinPartyEx`): GemRB binds both to one function; whether it reads the extra parameter is checked per action (see findings).", "",
	"## Actions with a GemRB problem or a duplicate id", "", "| Id | Name | Uses | GemRB | Orig | Where |", "|---|---|---|---|---|---|"]
for r in sc["actions"]:
	dup = r["name"].endswith("Ex")
	if r["status"] or dup:
		L.append("| %d | %s | %d | %s | %s | %s |" % (r["id"], r["name"], r["uses"], "bound with the base name: check the extra parameter" if dup else r["status"],
			"yes" if r["id"] in handled else "**no**", ", ".join(r["where"][:4])))
L += ["", "## Triggers with a GemRB problem", "", "| Id | Name | Uses | GemRB | Orig | Where |", "|---|---|---|---|---|---|"]
for r in sc["triggers"]:
	if r["status"]:
		L.append("| 0x%X | %s | %d | %s | %s | %s |" % (r["id"], r["name"], r["uses"], r["status"],
			"n/a (event)" if r["id"] < 0x4000 else ("yes" if r["id"] in ot else "no handler (always false)"), ", ".join(r["where"][:4])))
L += ["", "## All actions used", "", "| Id | Name | Uses | GemRB function |", "|---|---|---|---|"]
for r in sc["actions"]:
	L.append("| %d | %s | %d | `%s` |" % (r["id"], r["name"], r["uses"], r["gemrb"] or "—"))
open(os.path.join(OUT, "scripting.md"), "w", encoding="utf-8").write("\n".join(L) + "\n")

# ---------------- rules index
L = ["# PST-specific engine functions (PST:EE symbols)", "",
	"Every PST-only function in the PST:EE Linux binary, biggest first: the checklist for rules parity. Decompiled",
	"copies are in `.re/ee/dump/dec/` (local only, not committed).", "", "| Size | Function |", "|---|---|"]
for l in open("ee_pst_funcs.txt"):
	sz, fn = l.rstrip("\n").split("\t")
	L.append("| %s | `%s` |" % (sz, fn.replace("|", "\\|")))
open(os.path.join(OUT, "pst_functions.md"), "w", encoding="utf-8").write("\n".join(L) + "\n")
print("written")
